"""Canary values: generated by code at render/plant time, stored in MongoDB, never committed.

A canary id is "<kind>_<n>" (e.g. aws_access_key_1). The first time an id is used its value
is generated; afterwards the same id always resolves to the same value, so a credential the
attacker finds on one decoy works where the environment says it should (userdb, wiki).
"""
from __future__ import annotations

import secrets
import string
from datetime import datetime, timezone

from .filters import KINDS, PLACEHOLDER, placeholder_errors

_WORDS = ("Harbor", "Falcon", "Maple", "Orbit", "Copper", "Summit", "Willow", "Delta", "Cobalt", "Juniper")
_B32 = string.ascii_uppercase + "234567"
_ALNUM = string.ascii_letters + string.digits


def _rand(alphabet: str, n: int) -> str:
    return "".join(secrets.choice(alphabet) for _ in range(n))


def generate(kind: str) -> str:
    """A realistic-looking, unique fake credential. Not a real key of any service."""
    if kind == "password":
        return f"{secrets.choice(_WORDS)}{secrets.randbelow(9000) + 1000}{secrets.choice('!#$%')}{_rand(string.digits, 2)}"
    if kind == "aws_access_key":
        return "AKIA" + _rand(_B32, 16)
    if kind == "aws_secret_key":
        return _rand(_ALNUM + "+/", 40)
    if kind == "api_token":
        return "sk-" + _rand(_ALNUM, 40)
    if kind == "ssh_key":
        body = "\n".join(_rand(_ALNUM + "+/", 70) for _ in range(5))
        return f"-----BEGIN OPENSSH PRIVATE KEY-----\n{body}\n-----END OPENSSH PRIVATE KEY-----"
    raise ValueError(f"unknown canary kind {kind}")


def _kind(canary_id: str) -> str:
    kind = canary_id.rsplit("_", 1)[0]
    if kind not in KINDS:
        raise ValueError(f"unknown canary kind in {canary_id}")
    return kind


class CanaryRegistry:
    def __init__(self, db):
        self.col = db["canaries"]
        self.col.create_index("canary_id", unique=True)

    def resolve(self, canary_id: str) -> str:
        kind = _kind(canary_id)
        doc = self.col.find_one({"canary_id": canary_id})
        if doc is None:
            self.col.update_one({"canary_id": canary_id},
                                {"$setOnInsert": {"canary_id": canary_id, "kind": kind, "value": generate(kind),
                                                  "created_at": datetime.now(timezone.utc), "planted_in": []}},
                                upsert=True)
            doc = self.col.find_one({"canary_id": canary_id})
        return doc["value"]

    def substitute(self, text: str, where: dict | None = None) -> tuple[str, list[str]]:
        """Replace every placeholder with its value. -> (text, canary ids used). Bad placeholders raise."""
        errs = placeholder_errors(text)
        if errs:
            raise ValueError("; ".join(errs))
        used: list[str] = []

        def repl(m):
            cid = f"{m.group(1)}_{int(m.group(2))}"
            if cid not in used:
                used.append(cid)
            return self.resolve(cid)

        out = PLACEHOLDER.sub(repl, text)
        if where and used:
            self.col.update_many({"canary_id": {"$in": used}}, {"$addToSet": {"planted_in": where}})
        return out, used

    def values(self) -> dict[str, str]:
        """value -> canary id, for detecting use (collector)."""
        return {d["value"]: d["canary_id"] for d in self.col.find({}, {"value": 1, "canary_id": 1})}

    def find_used(self, text: str) -> list[str]:
        """Canary ids whose value appears in text (e.g. a login password or a command)."""
        if not text:
            return []
        return [cid for value, cid in self.values().items() if value and value in text]
